INSERT INTO districts (name, tamil_name, region, description, history, cultural_significance, area_sq_km, formed_year, tourist_attractions, cultural_heritage, famous_festivals, image, official_website, collector_designation) VALUES
('Chennai', 'சென்னை', 'North', 'The capital city of Tamil Nadu, Chennai is a vibrant metropolitan hub blending colonial heritage with ancient temple traditions, home to Kapaleeshwarar and Parthasarathy temples.', 'Chennai, formerly Madras, grew from a British settlement established in 1639 at Fort St. George. The area however has ancient roots with Mylapore and Triplicane being significant Pallava-era temple towns long before the colonial era.', 'Chennai is the gateway to South Indian culture, renowned for classical music, Bharatanatyam, and its historic temple architecture.', 426, 1639, ARRAY['Marina Beach','Kapaleeshwarar Temple','Fort St. George','Government Museum','San Thome Basilica'], ARRAY['Carnatic Music','Bharatanatyam','Temples of Mylapore'], ARRAY['Chennai Music Festival','Panguni Uthiram','Vinayagar Chaturthi'], 'https://images.pexels.com/photos/774282/pexels-photo-774282.jpeg?auto=compress&cs=tinysrgb&w=1200', 'https://www.chennaicorporation.gov.in', 'District Collector'),
('Chengalpattu', 'செங்கல்பட்டு', 'North', 'A historic district famous for Mahabalipuram''s UNESCO World Heritage shore temples and ancient rock-cut architecture.', 'Chengalpattu was carved out of Kancheepuram district. The region''s heritage dates to the Pallava dynasty with Mahabalipuram as their port city.', 'Home to Mahabalipuram, a UNESCO World Heritage Site showcasing Pallava rock-cut architecture.', 2945, 2019, ARRAY['Mahabalipuram Shore Temple','Pancha Rathas','Tiger Cave','Muttukadu Backwater'], ARRAY['Pallava Rock Architecture','Stone Carving Tradition'], ARRAY['Mamallapuram Dance Festival','Thai Poosam'], 'https://images.pexels.com/photos/37626302/pexels-photo-37626302.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Kancheepuram', 'காஞ்சிபுரம்', 'North', 'The "City of Thousand Temples," Kancheepuram is one of the seven sacred Hindu pilgrimage cities and famous for its silk sarees.', 'Kancheepuram was the capital of the Pallava dynasty from the 4th to 9th centuries and a major center of learning. It has been a sacred Hindu pilgrimage destination for over two millennia.', 'One of the Sapta Puri (seven sacred cities) and a foremost seat of Shaivism and Vaishnavism.', 4433, 1799, ARRAY['Ekambareswarar Temple','Kamakshi Amman Temple','Varadharaja Perumal Temple','Kailasanathar Temple'], ARRAY['Kancheepuram Silk','Temple Architecture','Sanskrit Learning'], ARRAY['Brahmotsavam','Sankara Jayanthi','Pongal'], 'https://images.pexels.com/photos/39498479/pexels-photo-39498479.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Tiruvallur', 'திருவள்ளூர்', 'North', 'A district blending temple heritage with industrial growth, home to the famous Tiruttani Murugan temple.', 'Tiruvallur district has historical significance with ancient temples dating to the Pallava and Chola periods. The name derives from "Tiru-Evul-ur," referring to the Veeraraghava Perumal temple.', 'Home to Tiruttani, one of the six abodes of Lord Murugan.', 3422, 1991, ARRAY['Tiruttani Murugan Temple','Veeraraghava Perumal Temple','Pulicat Lake'], ARRAY['Murugan Worship Tradition','Pallava Temples'], ARRAY['Thai Poosam','Vaikasi Visakam'], 'https://images.pexels.com/photos/10070972/pexels-photo-10070972.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Vellore', 'வேலூர்', 'North', 'A historic district known for the Vellore Fort, Jalakandeswarar Temple, and the golden Sripuram Lakshmi Narayani Temple.', 'Vellore has a rich history connected to the Vijayanagara Empire, Nawabs of Arcot, and the British. The Vellore Fort was built in the 16th century and played a key role in the 1806 sepoy mutiny.', 'A blend of military heritage and spiritual landmarks including the golden Sripuram temple.', 4235, 1911, ARRAY['Vellore Fort','Sripuram Golden Temple','Ratnagiri Murugan Temple','Jalakandeswarar Temple'], ARRAY['Vellore Fort Architecture','Temple Gold Work'], ARRAY['Kanda Shasti','Panguni Uthiram'], 'https://images.pexels.com/photos/11539838/pexels-photo-11539838.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Ranipet', 'ராணிபேட்டை', 'North', 'An industrial district with significant temple heritage, including the Yoga Narasimha Swamy temple at Sholinghur.', 'Ranipet was formed in 2019 by bifurcating Vellore district. The region has historical ties to the Arcot Nawabs and colonial-era industries.', 'Sholinghur is an important Narasimha worship center with hill temples.', 1908, 2019, ARRAY['Yoga Narasimha Swamy Temple Sholinghur','Veeraraghava Perumal Temple Sholinghur','Arcot Fort'], ARRAY['Narasimha Worship','Colonial History'], ARRAY['Narasimha Jayanthi','Brahmotsavam'], 'https://images.pexels.com/photos/40020598/pexels-photo-40020598.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Tirupathur', 'திருப்பத்தூர்', 'North', 'A district with diverse religious heritage featuring Narasimha and Murugan temples.', 'Tirupathur was formed in 2019 from Vellore district. The region has ancient temple traditions dating to the Pallava and Chola eras.', 'Known for the Yoga Narasimhar temple at Singarapettai and Kandaswamy temple.', 1787, 2019, ARRAY['Yoga Narasimhar Temple Singarapettai','Kandaswamy Temple Tirupathur','Jalakandeswarar Temple Ambur'], ARRAY['Temple Architecture','Leather Industry'], ARRAY['Kanda Shasti','Vaikasi Visakam'], 'https://images.pexels.com/photos/35341456/pexels-photo-35341456.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Tiruvannamalai', 'திருவண்ணாமலை', 'North', 'Home to the sacred Arunachala hill and the Arunachaleswarar Temple, one of the Pancha Bhoota Stalas representing fire.', 'Tiruvannamalai has been a sacred pilgrimage site for centuries, associated with the Arunachala hill. The Arunachaleswarar temple was expanded by the Chola kings. Sri Ramana Maharshi lived here in the early 20th century.', 'One of the Pancha Bhoota Stalas (fire element) and a major Shaivite pilgrimage center.', 6196, 1911, ARRAY['Arunachaleswarar Temple','Arunachala Hill','Sri Ramanasramam','Adi Annamalai Temple'], ARRAY['Arunachala Pilgrimage','Giri Valam Tradition','Ramana Maharshi Teachings'], ARRAY['Karthigai Deepam','Maha Shivaratri','Pournami Girivalam'], 'https://images.pexels.com/photos/26524953/pexels-photo-26524953.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Villupuram', 'விழுப்புரம்', 'North', 'A diverse district with ancient Vishnu and Shiva temples, including the Lakshmi Narasimha Swamy temple at Parikkal.', 'Villupuram district has a long history connected to the Pallava, Chola and Vijayanagara empires. Several temples here are ancient Divya Desams and Paadal Petra Sthalams.', 'Home to several sacred Vishnu temples and the Singavaram Ranganathar temple.', 7217, 1993, ARRAY['Lakshmi Narasimha Swamy Temple Parikkal','Singavaram Ranganathar Temple','Gingee Fort','Thiruvamathur Abirameswarar Temple'], ARRAY['Gingee Fort','Vishnu Temple Tradition'], ARRAY['Narasimha Jayanthi','Brahmotsavam'], 'https://images.pexels.com/photos/31695660/pexels-photo-31695660.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Kallakurichi', 'கள்ளக்குறிச்சி', 'North', 'A district with ancient temple heritage, including the Veeratteswarar and Ulagalantha Perumal temples at Thirukkoilur.', 'Kallakurichi was formed in 2019 from Villupuram district. Thirukkoilur is an ancient temple town with significant Shaivite and Vaishnavite heritage.', 'Thirukkoilur is one of the Divya Desams and a Paadal Petra Sthalam.', 3717, 2019, ARRAY['Veeratteswarar Temple Thirukkoilur','Ulagalantha Perumal Temple Thirukkoilur','Athulyanatheswarar Temple Arakandanallur','Kalrayan Hills'], ARRAY['Twin Temple Tradition','Tribal Heritage of Kalrayan Hills'], ARRAY['Maha Shivaratri','Vaikunda Ekadasi'], 'https://images.pexels.com/photos/37678479/pexels-photo-37678479.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Cuddalore', 'கடலூர்', 'Central', 'A coastal district home to the famous Nataraja Temple at Chidambaram, one of the Pancha Bhoota Stalas representing space.', 'Cuddalore has a rich colonial and temple history. Chidambaram has been a center of Shaivite worship for over a millennium, with the Nataraja temple expanded by the Chola kings.', 'Chidambaram Nataraja Temple is one of the Pancha Bhoota Stalas (space/akasha) and a foremost Shaivite pilgrimage site.', 3642, 1798, ARRAY['Nataraja Temple Chidambaram','Bhuvaraha Swamy Temple Srimushnam','Pataleeswarar Temple','Silver Beach'], ARRAY['Chidambaram Nataraja Worship','Bharatanatyam Origins','Annamacharya Tradition'], ARRAY['Arudra Darshanam','Natyanjali Festival','Masi Magam'], 'https://images.pexels.com/photos/35279373/pexels-photo-35279373.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Mayiladuthurai', 'மயிலாடுதுறை', 'Central', 'A temple district on the banks of the Cauvery, home to the Vaitheeswaran Koil and the Amritaghateswarar temple at Thirukadaiyur.', 'Mayiladuthurai was formed in 2020 from Nagapattinam district. The region has deep temple heritage along the Cauvery river, with several ancient Paadal Petra Sthalams.', 'Vaitheeswaran Koil is famous as a Mars (Sevvai) Sthalam in Navagraha pilgrimage. Thirukadaiyur is known for Amritaghateswarar and longevity poojas.', 1172, 2020, ARRAY['Mayuranathaswami Temple','Vaitheeswaran Koil','Amritaghateswarar Temple Thirukadaiyur','Cauvery River Banks'], ARRAY['Navagraha Temple Tradition','Cauvery River Pilgrimage'], ARRAY['Mayuranathar Brahmotsavam','Thai Poosam','Masi Magam'], 'https://images.pexels.com/photos/32547442/pexels-photo-32547442.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Nagapattinam', 'நாகப்பட்டினம்', 'Central', 'A coastal pilgrimage district with the Kayarohanaswami temple and the Navagraha temple at Sikkal.', 'Nagapattinam has a long maritime and temple history, dating to the Chola period when it was an important port. The region has several ancient Shaivite temples.', 'Sikkal Singaravelan temple is an important Murugan pilgrimage site. Kayarohanaswami is an ancient Shiva temple.', 2417, 1991, ARRAY['Kayarohanaswami Temple','Sikkal Singaravelan Temple','Soundararajaperumal Temple','Velankanni Basilica'], ARRAY['Coastal Temple Tradition','Murugan Worship'], ARRAY['Sikkal Festival','Soorasamharam'], 'https://images.pexels.com/photos/5138790/pexels-photo-5138790.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Tiruvarur', 'திருவாரூர்', 'Central', 'The birthplace of the Trinity of Carnatic music, home to the Thyagaraja temple with its famous Ajaba dance.', 'Tiruvarur has been a major Shaivite center since the Chola period. The Thyagaraja temple is one of the most ancient and significant Shiva temples in Tamil Nadu. The Trinity of Carnatic Music were born here.', 'Birthplace of Carnatic music Trinity and home to the Thyagaraja temple with the unique Ajaba Natanam.', 2337, 1991, ARRAY['Thyagaraja Temple','Rajagopalaswamy Temple Mannargudi','Saraswathi Temple Koothanur','Muthupettai Mangrove'], ARRAY['Carnatic Music Trinity','Thyagaraja Temple Traditions','Ajaba Dance'], ARRAY['Thyagaraja Aradhana','Masi Festival','Vasantotsavam'], 'https://images.pexels.com/photos/33895627/pexels-photo-33895627.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Thanjavur', 'தஞ்சாவூர்', 'Central', 'The cultural capital of Tamil Nadu, home to the UNESCO World Heritage Brihadeeswarar Temple built by Raja Raja Chola I.', 'Thanjavur was the capital of the Chola Empire during its zenith. The Brihadeeswarar Temple was built by Raja Raja Chola I in 1010 CE. Later it came under the Nayaks and Marathas.', 'Home to the Great Living Chola Temple, a UNESCO World Heritage Site, and a center of Tanjore art and classical music.', 3390, 1798, ARRAY['Brihadeeswarar Temple','Airavatesvara Temple Darasuram','Thanjavur Palace','Punnainallur Mariamman Temple','Tanjore Art Gallery'], ARRAY['Tanjore Painting','Chola Architecture','Carnatic Music'], ARRAY['Brihadeeswarar Brahmotsavam','Pongal','Natyanjali'], 'https://images.pexels.com/photos/5138790/pexels-photo-5138790.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Pudukkottai', 'புதுக்கோட்டை', 'Central', 'A district with rich archaeological heritage, rock-cut temples, and the Brahadambal and Viralimalai Murugan temples.', 'Pudukkottai was a princely state under the British. The region has numerous rock-cut temples from the Pallava and Pandya periods, and ancient megalithic sites.', 'Viralimalai is an important Murugan pilgrimage site. The district has unique rock-cut temple architecture.', 4690, 1974, ARRAY['Brahadambal Temple Thirukokarnam','Avudaiyarkoil','Viralimalai Murugan Temple','Sittannavasal Rock Paintings'], ARRAY['Rock-cut Temples','Megalithic Sites','Murugan Worship'], ARRAY['Viralimalai Festival','Skanda Shasti'], 'https://images.pexels.com/photos/34148386/pexels-photo-34148386.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Tiruchirappalli', 'திருச்சிராப்பள்ளி', 'Central', 'Home to the Sri Ranganathaswamy Temple at Srirangam — the largest functioning Hindu temple in the world — and the Rockfort Ucchi Pillayar temple.', 'Tiruchirappalli has a rich history from the Chola, Pandya, and Nayak periods. Srirangam has been a major Vaishnavite center for centuries. The Rockfort temple sits atop an ancient rock formation.', 'Srirangam is the foremost of the 108 Divya Desams. Jambukeswarar is one of the Pancha Bhoota Stalas (water).', 4511, 1798, ARRAY['Sri Ranganathaswamy Temple Srirangam','Jambukeswarar Temple Thiruvanaikaval','Ucchi Pillayar Temple Rockfort','Srirangam Temple Complex'], ARRAY['Vaishnavite Pilgrimage','Rockfort Heritage','Dravidian Architecture'], ARRAY['Vaikunta Ekadasi','Aani Brahmotsavam','Panguni Uthiram'], 'https://images.pexels.com/photos/37662256/pexels-photo-37662256.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Perambalur', 'பெரம்பலூர்', 'Central', 'A district with the famous Siruvachur Madura Kaliamman temple and ancient Shiva temples.', 'Perambalur was formed in 1995 from Tiruchirappalli district. The region has several ancient temples and is known for its cement and agricultural industries.', 'Siruvachur Madura Kaliamman is a powerful Shakthi shrine visited by devotees from across Tamil Nadu.', 1755, 1995, ARRAY['Siruvachur Madura Kaliamman Temple','Ekambareswarar Temple Chettikulam','Balasubramaniya Swamy Temple','Ranjankudi Fort'], ARRAY['Shakthi Worship','Rural Temple Architecture'], ARRAY['Navarathri','Masi Festival'], 'https://images.pexels.com/photos/36849624/pexels-photo-36849624.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Ariyalur', 'அரியலூர்', 'Central', 'A district known for the Gangaikonda Cholapuram Brihadeeswarar Temple and rich fossil heritage.', 'Ariyalur was formed in 2007 from Perambalur district. Gangaikonda Cholapuram was built by Rajendra Chola I as his capital after his northern conquests. The district is also rich in marine fossils.', 'Gangaikonda Cholapuram is a UNESCO World Heritage Site (as part of the Great Living Chola Temples).', 1940, 2007, ARRAY['Gangaikonda Cholapuram Temple','Kaliyuga Varadaraja Perumal Temple Kallankurichi','Siva Temple Melapaluvur','Ariyalur Fossil Fields'], ARRAY['Chola Temple Architecture','Fossil Heritage'], ARRAY['Maha Shivaratri','Brahmotsavam'], 'https://images.pexels.com/photos/36849683/pexels-photo-36849683.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Karur', 'கரூர்', 'Central', 'An ancient temple town with the Pasupatheeswarar temple and a rich textile heritage.', 'Karur has a history dating to the Chera, Chola, and Pandya periods. It was an important center on the ancient trade route. The Pasupatheeswarar temple is a Paadal Petra Sthalam.', 'Pasupatheeswarar is an ancient Shiva temple praised in the Tevaram. Karur is also a major textile export hub.', 2549, 1996, ARRAY['Pasupatheeswarar Temple','Kalyana Venkataramana Swamy Temple Thanthoni','Rathinagireeswarar Temple Ayyarmalai','Mayanur Barrage'], ARRAY['Chera Dynasty Heritage','Textile Weaving'], ARRAY['Maha Shivaratri','Brahmotsavam'], 'https://images.pexels.com/photos/7915949/pexels-photo-7915949.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Namakkal', 'நாமக்கல்', 'West', 'Famous for the Namakkal Anjaneyar temple, Narasimhaswamy temple, and the Ardhanareeswarar temple at Tiruchengode.', 'Namakkal district was formed in 1996 from Salem district. The region has ancient temple traditions, with the Narasimhaswamy temple and the hill-top Anjaneyar being major landmarks.', 'The 18-foot tall Anjaneyar idol is a unique open-air shrine. Tiruchengode Ardhanareeswarar is one of the Paadal Petra Sthalams.', 3429, 1996, ARRAY['Namakkal Anjaneyar Temple','Narasimhaswamy Temple','Ardhanareeswarar Temple Tiruchengode','Kolli Hills'], ARRAY['Hanuman Worship','Hill Temple Tradition'], ARRAY['Hanuman Jayanthi','Narasimha Jayanthi','Maha Shivaratri'], 'https://images.pexels.com/photos/32654427/pexels-photo-32654427.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Salem', 'சேலம்', 'West', 'A district surrounded by hills, home to the Sugavaneswarar temple, Kottai Mariamman, and the Skandasramam Murugan temple.', 'Salem has a history dating to ancient times, with references in inscriptions from the Chola and Pandya periods. The region is known for its steel, mango, and silk industries.', 'Skandasramam is a significant Murugan temple on a hill. Kottai Mariamman is a powerful Amman shrine.', 5245, 1798, ARRAY['Sugavaneswarar Temple','Kottai Mariamman Temple','Skandasramam Udayapatti','Yercaud Hill Station','Mettur Dam'], ARRAY['Hill Temple Tradition','Steel Industry Heritage'], ARRAY['Mariamman Festival','Kanda Shasti','Pongal'], 'https://images.pexels.com/photos/774282/pexels-photo-774282.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Dharmapuri', 'தருமபுரி', 'North', 'A district with the Theerthamalai temple and Chenraya Perumal temple, known for Hogenakkal falls.', 'Dharmapuri was formed in 1965 from Salem district. The region has connections to the Adhiyaman dynasty, one of the Kadaiyezhu Vallalgal (last seven great patrons).', 'Theerthamalai is an ancient Shiva pilgrimage site. The district is the gateway to Hogenakkal falls.', 4485, 1965, ARRAY['Kottai Kovil','Theerthamalai Theerthagireeswarar Temple','Chenraya Perumal Temple Adhiyamankottam','Hogenakkal Falls'], ARRAY['Adhiyaman Dynasty Heritage','Cauvery River Pilgrimage'], ARRAY['Maha Shivaratri','Panguni Uthiram'], 'https://images.pexels.com/photos/37626302/pexels-photo-37626302.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Krishnagiri', 'கிருஷ்ணகிரி', 'North', 'A district with the Chandrachoodeswarar temple at Hosur and agricultural heritage.', 'Krishnagiri was formed in 2004 from Dharmapuri district. The region has historical connections to the Vijayanagara Empire and Tipu Sultan.', 'Chandrachoodeswarar temple at Hosur is a significant Shiva shrine. The district is known for mango cultivation.', 5143, 2004, ARRAY['Chandrachoodeswarar Temple Hosur','Venugopala Swamy Temple','Kattuveera Anjaneya Temple','Krishnagiri Dam'], ARRAY['Vijayanagara Temple Architecture','Mango Cultivation Heritage'], ARRAY['Maha Shivaratri','Brahmotsavam'], 'https://images.pexels.com/photos/39498479/pexels-photo-39498479.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Erode', 'ஈரோடு', 'West', 'A textile and agricultural district with the Thindal Murugan, Bannari Mariamman, and Sangameswarar temples.', 'Erode was formed in 1979 from Coimbatore district. The region has ancient temple traditions along the Bhavani and Cauvery rivers.', 'Sangameswarar at Bhavani is at the confluence of three rivers — a sacred Triveni Sangamam of South India.', 4531, 1979, ARRAY['Thindal Murugan Temple','Bannari Mariamman Temple','Sangameswarar Temple Bhavani','Kodiveri Dam'], ARRAY['River Confluence Pilgrimage','Textile Industry'], ARRAY['Bannari Mariamman Festival','Kanda Shasti','Pongal'], 'https://images.pexels.com/photos/10070972/pexels-photo-10070972.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Tiruppur', 'திருப்பூர்', 'West', 'A textile hub with the Avinashi Lingeswarar and Sivanmalai Murugan temples.', 'Tiruppur was formed in 2009 from Coimbatore and Erode districts. The region is known globally for its cotton knitwear exports.', 'Sivanmalai is a hill-top Murugan temple. Avinashi Lingeswarar is an ancient Shiva temple.', 4691, 2009, ARRAY['Avinashi Lingeswarar Temple','Sivanmalai Murugan Temple','Tirumuruganpoondi Murugan Temple','Tiruppur Kumaran Memorial'], ARRAY['Knitwear Industry','Murugan Hill Temple'], ARRAY['Kanda Shasti','Thai Poosam'], 'https://images.pexels.com/photos/11539838/pexels-photo-11539838.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Coimbatore', 'கோயம்புத்தூர்', 'West', 'The "Manchester of South India," home to the Marudhamalai Murugan, Perur Pateeswarar, and Eachanari Vinayagar temples.', 'Coimbatore has a history connected to the Kongu Cholas, Vijayanagara Empire, and later the British. The region developed as a major industrial center while retaining its temple heritage.', 'Marudhamalai is a significant Murugan hill temple. Perur Pateeswarar is an ancient Paadal Petra Sthalam.', 4723, 1798, ARRAY['Marudhamalai Murugan Temple','Perur Pateeswarar Temple','Eachanari Vinayagar Temple','Siruvani Waterfalls','VOC Park'], ARRAY['Kongu Temple Architecture','Industrial Heritage','Textile Industry'], ARRAY['Kanda Shasti','Panguni Uthiram','Vinayagar Chaturthi'], 'https://images.pexels.com/photos/40020598/pexels-photo-40020598.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('The Nilgiris', 'நீலகிரி', 'West', 'A hill district known for its tea estates, cool climate, and the Elk Hill Murugan temple at Ooty.', 'The Nilgiris became a district in 1868 under British administration. The region is home to indigenous Toda, Badaga, and Kota tribes with unique cultural traditions.', 'Elk Hill Murugan temple is the main spiritual landmark. The Toda temple reflects indigenous tribal heritage.', 2545, 1868, ARRAY['Elk Hill Murugan Temple Ooty','Botanical Garden','Doddabetta Peak','Ooty Lake','Coonoor Tea Estates'], ARRAY['Toda Tribal Heritage','Tea Plantation Culture','Hill Station Architecture'], ARRAY['Tea and Tourism Festival','Kanda Shasti'], 'https://images.pexels.com/photos/35341456/pexels-photo-35341456.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Dindigul', 'திண்டுக்கல்', 'Central', 'Home to the famous Palani Dhandayuthapani Swamy temple — one of the six abodes of Lord Murugan.', 'Dindigul has a history connected to the Madurai Nayaks and Tipu Sultan. The Dindigul Fort is a historic landmark. Palani has been a major Murugan pilgrimage center for centuries.', 'Palani is the third of the Arupadaiveedu (six abodes of Murugan). The temple is visited by millions annually.', 6058, 1860, ARRAY['Palani Dhandayuthapani Temple','Abirami Amman Temple','Soundararaja Perumal Temple Thadikombu','Dindigul Fort'], ARRAY['Murugan Pilgrimage','Fort Architecture','Lock-making Tradition'], ARRAY['Thai Poosam','Panguni Uthiram','Kanda Shasti','Soorasamharam'], 'https://images.pexels.com/photos/31695660/pexels-photo-31695660.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Madurai', 'மதுரை', 'South', 'The "Temple City" and ancient capital of the Pandyas, home to the magnificent Meenakshi Amman Temple.', 'Madurai is one of the oldest continuously inhabited cities in the world, serving as the capital of the Pandya dynasty. The Meenakshi Temple was expanded by the Nayak kings in the 16th-17th centuries.', 'The Meenakshi Amman Temple is one of India''s most significant temple complexes. Thiruparankundram is the first of the six abodes of Murugan.', 3741, 1798, ARRAY['Meenakshi Amman Temple','Koodal Azhagar Temple','Thiruparankundram Murugan Temple','Thirumalai Nayakkar Palace','Vandiyur Mariamman Teppakulam'], ARRAY['Pandya Architecture','Nayak Temple Architecture','Tamil Sangam Literature'], ARRAY['Meenakshi Kalyanam','Chithirai Festival','Aani Brahmotsavam','Float Festival'], 'https://images.pexels.com/photos/33895627/pexels-photo-33895627.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Theni', 'தேனி', 'South', 'A scenic district on the Western Ghats foothills with the Kuchanur Saneeswaran and Periyakulam Balasubramanya temples.', 'Theni was formed in 1996 from Madurai district. The region has agricultural and temple heritage, with several ancient shrines in the foothills.', 'Kuchanur is one of the few dedicated Saneeswaran (Saturn) temples. Devadanapatti Kamatchi Amman is a hill shrine.', 2892, 1996, ARRAY['Kuchanur Saneeswaran Temple','Balasubramanya Temple Periyakulam','Kamatchi Amman Temple Devadanapatti','Megamalai','Suruli Falls'], ARRAY['Navagraha Worship','Hill Temple Tradition'], ARRAY['Sani Peyarchi','Thai Poosam'], 'https://images.pexels.com/photos/37678479/pexels-photo-37678479.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Sivagangai', 'சிவகங்கை', 'South', 'A historic district with the Karpaga Vinayagar temple at Pillayarpatti and Kalaiyarkoil.', 'Sivagangai was the seat of the Marudu brothers, freedom fighters who fought against the British. The region has ancient cave temples and Murugan worship traditions.', 'Pillayarpatti Karpaga Vinayagar is a unique rock-cut Ganesha temple. Kalaiyarkoil is a historic Shiva temple.', 4189, 1984, ARRAY['Karpaga Vinayagar Temple Pillayarpatti','Kaleswarar Temple Kalaiyarkoil','Vairavanpatti Vairavar Temple','Sivagangai Palace','Vettangudi Bird Sanctuary'], ARRAY['Rock-cut Ganesha','Marudu Brothers Heritage'], ARRAY['Vinayagar Chaturthi','Maha Shivaratri'], 'https://images.pexels.com/photos/35279373/pexels-photo-35279373.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Ramanathapuram', 'இராமநாதபுரம்', 'South', 'Home to the Ramanathaswamy Temple at Rameswaram — one of the twelve Jyotirlingas and a Char Dham site.', 'Ramanathapuram has a rich history connected to the Sethupathi kings. Rameswaram is linked to the Ramayana — Lord Rama is said to have worshipped Shiva here after the Lanka war.', 'Rameswaram is one of the 12 Jyotirlingas and one of the four Char Dham pilgrimage sites. The temple corridor is an architectural marvel.', 4163, 1798, ARRAY['Ramanathaswamy Temple Rameswaram','Mangalanathaswamy Temple Uthirakosamangai','Bhadrakali Amman Temple Devipattinam','Dhanushkodi','Pamban Bridge'], ARRAY['Ramayana Heritage','Jyotirlinga Pilgrimage','Sethupathi Dynasty'], ARRAY['Maha Shivaratri','Rama Navami','Arudra Darshanam'], 'https://images.pexels.com/photos/34148386/pexels-photo-34148386.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Virudhunagar', 'விருதுநகர்', 'South', 'Home to the Andal temple at Srivilliputhur — birthplace of Andal and one of the 108 Divya Desams.', 'Virudhunagar was formed in 1985 from Ramanathapuram district. Srivilliputhur has been a major Vaishnavite center for centuries, known as the birthplace of the poet-saint Andal.', 'Srivilliputhur Andal Temple is one of the 108 Divya Desams and the birthplace of Andal. The temple tower is the emblem of the Tamil Nadu government.', 4283, 1985, ARRAY['Andal Temple Srivilliputhur','Shenbagathoppu Kattazhagar Temple','Venkatachalapathy Temple Srivilliputhur','Srivilliputhur Grizzled Squirrel Sanctuary'], ARRAY['Andal and Vaishnavite Tradition','Tamil Nadu State Emblem Temple Tower'], ARRAY['Aadi Pooram','Vaikunta Ekadasi','Pongal'], 'https://images.pexels.com/photos/32547442/pexels-photo-32547442.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Tenkasi', 'தென்காசி', 'South', 'The "Varanasi of the South," home to the Kasi Viswanathar temple and the Kumaraswamy temple at Panpoli.', 'Tenkasi was formed in 2019 from Tirunelveli district. The Kasi Viswanathar temple was built by the Pandya kings as a southern alternative to Kashi.', 'Kasi Viswanathar is a major Shiva pilgrimage site. Sankaranarayanaswamy at Sankarankovil represents the union of Shiva and Vishnu.', 2439, 2019, ARRAY['Kasi Viswanathar Temple','Thirumalai Kumaraswamy Temple Panpoli','Sankaranarayanaswamy Temple Sankarankovil','Courtallam Falls'], ARRAY['Pandya Temple Architecture','Courtallam Spa Tradition'], ARRAY['Maha Shivaratri','Aadi Festival','Rathotsavam'], 'https://images.pexels.com/photos/5138790/pexels-photo-5138790.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Tirunelveli', 'திருநெல்வேலி', 'South', 'A historic city on the banks of the Thamirabarani river, home to the Nellaiappar Temple and Papanasanathar temple.', 'Tirunelveli has a long history from the Pandya, Chola, and Nayak periods. The Nellaiappar Temple is an ancient twin temple dedicated to Shiva and Parvati. The district is known for its river Thamirabarani.', 'Nellaiappar is a major Paadal Petra Sthalam. Papanasanathar at Papanasam is an ancient Shiva temple on the river.', 6700, 1790, ARRAY['Nellaiappar Temple','Krishnapuram Venkatachalapathy Temple','Papanasanathar Temple Papanasam','Courtallam Falls','Manimuthar Dam'], ARRAY['Pandya Architecture','Thamirabarani River Heritage','Halwa Tradition'], ARRAY['Aani Brahmotsavam','Arudra Darshanam','Thai Poosam'], 'https://images.pexels.com/photos/33895627/pexels-photo-33895627.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Thoothukudi', 'தூத்துக்குடி', 'South', 'A coastal district with the Subramaniya Swamy temple at Tiruchendur — one of the six abodes of Lord Murugan.', 'Thoothukudi (Tuticorin) has a long maritime history as a pearl fishing and trading port. Tiruchendur has been a major Murugan pilgrimage center for centuries.', 'Tiruchendur is the only Arupadaiveedu located on the seashore. The temple commemorates Murugan''s victory over Surapadman.', 4621, 1986, ARRAY['Subramaniya Swamy Temple Tiruchendur','Sankara Rameswarar Temple','Kalugasalamoorthy Temple Kazhugumalai','Thoothukudi Port','Pearl City Beach'], ARRAY['Murugan Pilgrimage','Pearl Fishing Heritage'], ARRAY['Soorasamharam','Skanda Shasti','Vaikasi Visakam'], 'https://images.pexels.com/photos/26524953/pexels-photo-26524953.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector'),
('Kanniyakumari', 'கன்னியாகுமரி', 'South', 'India''s southernmost district, where three seas meet, home to the Bhagavathy Amman and Thanumalayan temples.', 'Kanniyakumari has a rich history connected to the Travancore kingdom and ancient temple traditions. The Bhagavathy Amman temple is one of the 51 Shakti Peethas.', 'Bhagavathy Amman is one of the Shakti Peethas. The Suchindram Thanumalayan temple represents the Trimurti — Shiva, Vishnu, and Brahma.', 1672, 1949, ARRAY['Bhagavathy Amman Temple','Thanumalayan Temple Suchindram','Nagaraja Temple Nagercoil','Vivekananda Rock Memorial','Sunrise Point'], ARRAY['Shakti Peetha','Trimurti Worship','Sunrise Pilgrimage'], ARRAY['Navarathri','Chaitra Pournami','Maha Shivaratri'], 'https://images.pexels.com/photos/34148386/pexels-photo-34148386.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, 'District Collector')
